#!/bin/sh
repositories_menu(){ while :; do c=$(ui_menu Repositories "Detected package manager: $PKG_MGR" native 'Open native package-manager repository menu' files 'List repository files' edit 'Edit primary repository file' backup 'Back up repository configuration' test 'Test repository update' custom 'Add a custom repository line') || { _menu_rc=$?; [ "$_menu_rc" -eq "${UI_MENU_BACK_RC:-90}" ] && return 0; return "$_menu_rc"; }; case $c in native) case $PKG_MGR in apt) apt_menu;; apk) apk_menu;; pacman) pacman_menu;; *) ui_msg Repositories 'No specialized adapter yet; use Edit.';; esac;; files) ui_text Files "$(find /etc -maxdepth 4 -type f \( -name '*sources*' -o -name '*repo*' -o -name 'mirrorlist' -o -name 'make.conf' \) 2>/dev/null)";; edit) case $PKG_MGR in apt) edit_file /etc/apt/sources.list;; apk) edit_file /etc/apk/repositories;; pacman) edit_file /etc/pacman.d/mirrorlist;; dnf|yum) edit_file /etc/yum.repos.d/ish-aok.repo;; emerge) edit_file /etc/portage/make.conf;; *) edit_file /etc/repositories;; esac;; backup) d="$BACKUP_DIR/repos-$(date +%Y%m%d-%H%M%S)"; mkdir -p "$d"; for x in /etc/apt /etc/apk /etc/pacman.conf /etc/pacman.d /etc/yum.repos.d /etc/portage; do [ -e "$x" ] && as_root cp -Rp "$x" "$d/"; done; ui_msg Backup "$d";; test) run_capture Update pkg_update;; custom) line=$(ui_input Repository 'Repository line:' '') || continue; case $PKG_MGR in apt) append_unique /etc/apt/sources.list "$line";; apk) append_unique /etc/apk/repositories "$line";; pacman) append_unique /etc/pacman.d/mirrorlist "$line";; *) ui_msg Repository 'Use the native repository editor.';; esac;; esac; done; }
